package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.Document;import com.casystem.onboarding.repository.DocumentRepository;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.mock.web.MockMultipartFile;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class DocumentControllerTest{@Mock DocumentRepository docs;@Mock TokenService tokens;@Mock CryptoService crypto;@Mock AuditService audit;@Mock HttpServletRequest req;DocumentController c;Document d;@BeforeEach void init(){MockitoAnnotations.openMocks(this);c=new DocumentController(docs,tokens,crypto,audit);when(tokens.userId(anyString())).thenReturn(3L);when(req.getRemoteAddr()).thenReturn("ip");d=new Document();d.setId(9L);d.setUserId(3L);d.setFileName("a.pdf");d.setContentType("application/pdf");d.setCreatedAt(LocalDateTime.now());d.setEncryptedContent(new byte[]{9});when(docs.findByIdAndUserIdAndDeletedFalse(9L,3L)).thenReturn(Optional.of(d));when(crypto.encryptBytes(any())).thenReturn(new byte[]{9});when(crypto.decryptBytes(any())).thenReturn(new byte[]{1,2});when(docs.save(any())).thenAnswer(i->{Document x=i.getArgument(0);if(x.getId()==null)x.setId(10L);return x;});}
@Test void lista(){when(docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(3L)).thenReturn(List.of(d));assertEquals(1,c.list("h").size());}
@Test void cargaDescargaReemplazaYElimina()throws Exception{var f=new MockMultipartFile("file","x.pdf","application/pdf",new byte[]{1});assertEquals("Documento cargado",c.upload("h",f,req).get("message"));assertEquals(2,c.download("h",9L,req).getBody().length);var f2=new MockMultipartFile("file","b.png","image/png",new byte[]{2});assertEquals("Documento reemplazado",c.replace("h",9L,f2,req).get("message"));assertEquals("b.png",d.getFileName());assertEquals("Documento eliminado",c.delete("h",9L,req).get("message"));assertTrue(d.isDeleted());}
@Test void rechazaArchivoVacio() {var f=new MockMultipartFile("file","x.pdf","application/pdf",new byte[]{});assertThrows(IllegalArgumentException.class,()->c.upload("h",f,req));assertThrows(IllegalArgumentException.class,()->c.replace("h",9L,f,req));}}
